func Decode(in []byte) (*InputRecord, error) {
	r := &reader{buf: in}
	r.ws()
	v, err := r.decodeInputRecord()
	if err != nil {
		return nil, err
	}
	r.ws()
	if r.pos < len(r.buf) {
		return nil, r.refuse("trailing_bytes")
	}
	return v, nil
}

// ToJSON writes one record of this package, given as a value or a pointer,
// as JSON laid out as its documents are and without the document terminator.
// Anything else, a nil pointer included, is refused with wrong_type.
func ToJSON(v any) (out []byte, err error) {
	defer func() {
		if p := recover(); p != nil {
			if e, ok := p.(*Refusal); ok {
				out, err = nil, e
				return
			}
			panic(p)
		}
	}()
	switch v := v.(type) {
	case LegacyHeader:
		return encLegacyHeader(nil, &v, 0), nil
	case *LegacyHeader:
		if v == nil {
			return nil, &Refusal{Word: "wrong_type"}
		}
		return encLegacyHeader(nil, v, 0), nil
	case InputRecord:
		return encInputRecord(nil, &v, 0), nil
	case *InputRecord:
		if v == nil {
			return nil, &Refusal{Word: "wrong_type"}
		}
		return encInputRecord(nil, v, 0), nil
	case Payload:
		return encPayload(nil, &v, 0), nil
	case *Payload:
		if v == nil {
			return nil, &Refusal{Word: "wrong_type"}
		}
		return encPayload(nil, v, 0), nil
	case TimestampValue:
		return encTimestampValue(nil, &v, 0), nil
	case *TimestampValue:
		if v == nil {
			return nil, &Refusal{Word: "wrong_type"}
		}
		return encTimestampValue(nil, v, 0), nil
	}
	return nil, &Refusal{Word: "wrong_type"}
}

// FromJSON reads one record from data into v, a pointer to a record of this
// package. A refused input returns *Refusal.
func FromJSON(data []byte, v any) error {
	r := &reader{buf: data}
	r.ws()
	switch p := v.(type) {
	case *LegacyHeader:
		if p == nil {
			return &Refusal{Word: "wrong_type"}
		}
		x, err := r.decodeLegacyHeader()
		if err != nil {
			return err
		}
		r.ws()
		if r.pos < len(r.buf) {
			return r.refuse("trailing_bytes")
		}
		*p = *x
		return nil
	case *InputRecord:
		if p == nil {
			return &Refusal{Word: "wrong_type"}
		}
		x, err := r.decodeInputRecord()
		if err != nil {
			return err
		}
		r.ws()
		if r.pos < len(r.buf) {
			return r.refuse("trailing_bytes")
		}
		*p = *x
		return nil
	case *Payload:
		if p == nil {
			return &Refusal{Word: "wrong_type"}
		}
		x, err := r.decodePayload()
		if err != nil {
			return err
		}
		r.ws()
		if r.pos < len(r.buf) {
			return r.refuse("trailing_bytes")
		}
		*p = *x
		return nil
	case *TimestampValue:
		if p == nil {
			return &Refusal{Word: "wrong_type"}
		}
		x, err := r.decodeTimestampValue()
		if err != nil {
			return err
		}
		r.ws()
		if r.pos < len(r.buf) {
			return r.refuse("trailing_bytes")
		}
		*p = *x
		return nil
	}
	return &Refusal{Word: "wrong_type"}
}

// refusals is in the order two of them are chosen between.

var refusals = []string{"malformed", "bad_string", "number_spelling", "wrong_type", "bad_timestamp", "depth_exceeded", "duplicate_key", "duplicate_field", "unknown_field", "missing_field", "trailing_bytes"}

func refusalRank(word string) int {
	for i, w := range refusals {
		if w == word {
			return i
		}
	}
	return -1
}

