func DecodeLegacyHeaderAt(in []byte,depth,limit int)(*LegacyHeader,int,error){r:=&reader{buf:in,depth:depth,limit:limit};if depth<0||limit<1{return nil,0,r.refuse("depth_exceeded")};r.ws();v,e:=r.decodeLegacyHeader();return v,r.pos,e}
func EncodeLegacyHeaderAt(v *LegacyHeader,depth int)[]byte{if depth<0||depth>=64{panic(&Refusal{Word:"depth_exceeded"})};out:=encLegacyHeader(nil,v,depth);if _,_,e:=DecodeLegacyHeaderAt(out,depth,64);e!=nil{panic(e)};return out}
