func DecodeLegacyHeader(in []byte)(*LegacyHeader,error){v,n,e:=DecodeLegacyHeaderAt(in,0,64);if e!=nil{return nil,e};r:=&reader{buf:in,pos:n};r.ws();if r.pos!=len(in){return nil,r.refuse("trailing_bytes")};return v,nil}

